import{_ as o,o as a,c as r,a2 as s}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"Estado del Servicio","description":"","frontmatter":{},"headers":[],"relativePath":"es-ES/user-guide/settings/service-status.md","filePath":"es-ES/user-guide/settings/service-status.md","lastUpdated":1785993908000}'),t={name:"es-ES/user-guide/settings/service-status.md"};function n(i,e,l,d,c,p){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="estado-del-servicio" tabindex="-1">Estado del Servicio <a class="header-anchor" href="#estado-del-servicio" aria-label="Permalink to &quot;Estado del Servicio&quot;">​</a></h1><p>Gestiona el servicio de indexación en segundo plano, y te da una vista en vivo de sus registros.</p><h2 id="control-del-servicio" tabindex="-1">Control del servicio <a class="header-anchor" href="#control-del-servicio" aria-label="Permalink to &quot;Control del servicio&quot;">​</a></h2><p>Una tarjeta de estado muestra el estado actual del indexador elevado — <strong>Instalando</strong>, <strong>Indexando</strong>, <strong>Listo</strong> (con un recuento en vivo de archivos/carpetas), o <strong>Error</strong> — con un icono a juego (spinner, marca de verificación, o insignia de error).</p><p>Un botón <strong>Instalar e iniciar servicio</strong> aparece solo cuando el servicio aún no está instalado o ha tenido un error; una vez instalado y en ejecución, no hay ningún control manual de inicio/detención/desinstalación en esta página — se espera que el servicio simplemente siga funcionando en segundo plano.</p><h2 id="registros" tabindex="-1">Registros <a class="header-anchor" href="#registros" aria-label="Permalink to &quot;Registros&quot;">​</a></h2><p>Tres pestañas — <strong>App</strong>, <strong>Hook</strong>, <strong>Service</strong> — correspondientes a los tres procesos que ejecuta Lertaro (el indexador elevado en segundo plano, la App por usuario con la que interactúas, y el proceso de hook de teclado). Cada pestaña muestra las líneas de registro de ese proceso, coloreadas según el nivel.</p><ul><li>Desplegable de <strong>filtro de nivel</strong> — Todos / Error / Warn / Info / Debug.</li><li><strong>Cuadro de búsqueda</strong> — filtra las líneas visibles por palabra clave, combinado con el filtro de nivel.</li><li>Botón <strong>Borrar</strong> — vacía el registro de la pestaña seleccionada en ese momento. Borrar el registro de la pestaña Service se enruta a través del propio servicio (el proceso de la App no tiene permiso para escribir en él directamente); los registros de App y Hook se borran directamente, ya que son archivos por usuario.</li></ul><p>Este es el primer lugar donde mirar al solucionar problemas — ver <a href="./../troubleshooting.html#¿sigues-atascado">Solución de problemas</a>.</p>',9)])])}const v=o(t,[["render",n]]);export{g as __pageData,v as default};
